import{CHARACTERS}from'./characters.js';
export const ARENA={width:360,height:520,padding:22,floor:482},TEST_DURATION=30;
const MOVES=[{id:'charge',name:'黑風突擊',windup:.9},{id:'blade',name:'霸刀蓄力',windup:1.15},{id:'spin',name:'旋風斬',windup:1.05}];
export function createPrototypeState(team=['guan','zhangfei','hero']){return{running:true,complete:false,timeLeft:30,team:[...team],core:{x:180,y:460,vx:0,vy:0,r:22,bottomTime:.01,dashTime:0,powerAttack:0,invulnerable:0},boss:{x:180,y:112,r:50,maxHp:42000,hp:42000,flash:0,recoilX:0,move:null,moveIn:1.7,weakSide:0},combo:0,maxCombo:0,comboTime:0,power:0,powerTier:0,dashCooldown:0,breakGauge:0,breakIn:0,skillGauge:0,skill:null,skillIndex:0,skillCount:0,buff:null,wallStacks:0,雷能:0,hp:100,shield:0,history:[],events:[],pending:[],bossContact:false,hitStop:0,stats:{flips:0,perfectFlips:0,dashes:0,counters:0,perfectCounters:0,powerFlips:0,skills:0,ultimates:0,hits:0,weakHits:0,breaks:0,healing:0,damage:0,wallHits:0}};}
function emit(s,type,data={}){s.events.push({type,life:data.life||.7,...data});if(s.events.length>70)s.events.splice(0,s.events.length-70);}
export function getComboRank(n){return n>=100?'天下無雙':n>=50?'戰意沸騰':n>=30?'無雙':n>=20?'猛攻':n>=10?'疾風':'';}
export function getWeakPoint(s){const b=s.boss;return b.weakSide===0?{x:b.x-45,y:b.y-4}:b.weakSide===1?{x:b.x,y:b.y-51}:{x:b.x+45,y:b.y-4};}
function powerUpdate(s){s.power=Math.min(100,s.combo*2);s.powerTier=s.combo>=50?4:s.combo>=35?3:s.combo>=20?2:s.combo>=10?1:0;}
function hit(s,{kind='normal',actor=s.team[0],x=s.boss.x,y=s.boss.y,mult=1,breakAdd=5}={}){const ch=CHARACTERS[actor],wp=getWeakPoint(s),weak=Math.hypot(x-wp.x,y-wp.y)<47||kind.includes('weak');s.combo++;s.maxCombo=Math.max(s.maxCombo,s.combo);s.comboTime=s.buff?.type==='combo'?3.2:2.35;s.stats.hits++;if(weak)s.stats.weakHits++;let damage=(105+(kind.includes('dash')?80:0)+(kind.includes('power')?180:0))*mult;if(actor==='guan'&&weak)damage*=s.breakIn?1.9:1.35;if(actor==='commander')damage*=1+(1-s.boss.hp/s.boss.maxHp)*.8;if(actor==='tiger')damage*=1+Math.min(.5,s.combo/100);if(s.breakIn)damage*=1.6;damage=Math.round(damage);s.boss.hp=Math.max(0,s.boss.hp-damage);s.stats.damage+=damage;s.breakGauge=Math.min(100,s.breakGauge+breakAdd+(weak?15:0)+(actor==='zhangfei'?12:0));s.boss.flash=.11;s.boss.recoilX=(x<s.boss.x?1:-1)*(kind.includes('power')?15:7);s.hitStop=actor==='zhangfei'?.085:.035;emit(s,weak?'weak-hit':'hit',{text:`${weak?'WEAK ':''}-${damage}`,x:s.boss.x,y:s.boss.y,color:ch.color});powerUpdate(s);if(s.breakGauge>=100&&!s.breakIn){s.breakGauge=0;s.breakIn=3.5;s.stats.breaks++;s.boss.move=null;emit(s,'break',{text:'BOSS BREAK！',x:180,y:195,life:1});}}
function startMove(s){const m=MOVES[(s.stats.counters+s.stats.hits)%3];s.boss.move={...m,elapsed:0,counterFrom:m.windup-.58,perfectFrom:m.windup-.25};emit(s,'warning',{text:m.name,x:180,y:220,life:m.windup});if(s.team.includes('captain')&&m.id!=='charge'&&s.skillGauge>35){s.shield=1;s.skillGauge-=25;emit(s,'guard',{text:'鐵壁軍陣',x:180,y:370,life:1});}}
function updateBoss(s,dt){if(s.breakIn)return;if(!s.boss.move){s.boss.moveIn-=dt;if(s.boss.moveIn<=0)startMove(s);return;}const m=s.boss.move;m.elapsed+=dt;if(m.elapsed>=m.windup){if(s.shield){s.shield=0;hit(s,{kind:'counter',actor:'captain',mult:1.5,breakAdd:24});emit(s,'guard-counter',{text:'鐵壁反擊！',x:180,y:300});}else if(s.core.invulnerable<=0){s.hp=Math.max(0,s.hp-(s.team.includes('captain')?7:12));s.combo=Math.max(0,s.combo-7);emit(s,'hurt',{text:'隊伍受擊！',x:s.core.x,y:s.core.y-30});}s.boss.move=null;s.boss.moveIn=1.9;}}
export function getActionHint(s){if(s.boss.move&&s.boss.move.elapsed>=s.boss.move.counterFrom)return s.boss.move.elapsed>=s.boss.move.perfectFrom?'PERFECT COUNTER！':'COUNTER DASH！';if(s.core.y>=442)return s.powerTier?`POWER FLIP ${s.powerTier===4?'MAX':'ⅠⅡⅢ'[s.powerTier-1]}`:'FLIP';return s.dashCooldown<=0?'DASH':'DASH 充能中';}
export function tapPrototype(s){if(!s.running||s.complete||s.skill)return{type:'ignored'};const c=s.core,bottom=c.y>=442;if(bottom){const perfect=c.bottomTime>0&&c.bottomTime<=.32,tier=s.powerTier,leader=s.team[0];c.vx=(c.x<180?1:-1)*(tier?82:42);c.vy=-(perfect?700:650)-tier*32;c.bottomTime=0;c.powerAttack=tier;s.dashCooldown=.22;s.stats.flips++;if(perfect){s.stats.perfectFlips++;s.skillGauge+=leader==='hero'?28:leader==='liubei'?20:13;if(s.team.includes('liubei')){s.hp=Math.min(100,s.hp+4);s.stats.healing+=4;}emit(s,'perfect',{text:'PERFECT FLIP！',x:180,y:402});}if(tier){s.stats.powerFlips++;applyLeaderSynergy(s,leader,tier);s.powerTier=0;s.power=0;emit(s,'power',{text:`${CHARACTERS[leader].synergy}・POWER ${tier===4?'MAX':'ⅠⅡⅢ'[tier-1]}`,x:180,y:350,life:1});}return{type:tier?'power-flip':'flip',perfect,tier};}if(s.dashCooldown>0)return{type:'cooldown'};let counter=0;if(s.boss.move&&s.boss.move.elapsed>=s.boss.move.counterFrom){counter=s.boss.move.elapsed>=s.boss.move.perfectFrom?2:1;s.boss.move=null;s.boss.moveIn=1.6;s.core.invulnerable=.65;s.stats.counters++;if(counter===2){s.stats.perfectCounters++;if(s.team.includes('hero'))s.skillGauge+=24;}s.breakGauge+=counter===2?30:20;emit(s,'counter',{text:counter===2?'PERFECT COUNTER！':'COUNTER DASH！',x:s.core.x,y:s.core.y-32});}const dx=s.boss.x-c.x,dy=s.boss.y-c.y,d=Math.max(1,Math.hypot(dx,dy));c.vx=dx/d*(counter?770:660);c.vy=dy/d*(counter?770:660);c.dashTime=.24;s.dashCooldown=s.buff?.type==='haste'?.48:.82;s.stats.dashes++;return{type:counter===2?'perfect-counter':counter?'counter-dash':'dash'};}
function applyLeaderSynergy(s,id,tier){if(id==='guan')s.pending.push({delay:.09,actor:id,mult:1.4,kind:'power-weak',breakAdd:8});else if(id==='zhangfei')s.breakGauge+=18+tier*4;else if(id==='liubei'){s.hp=Math.min(100,s.hp+5+tier);s.comboTime+=.8;}else if(id==='blackwind')s.buff={type:'combo',time:2.2};else if(id==='tiger')s.buff={type:'burn',time:2.4};else if(id==='thunder')s.pending.push({delay:.08,actor:id,mult:1.25,kind:'power-pierce',breakAdd:8});else if(id==='zhangbao')s.雷能=Math.min(5,s.雷能+tier);else if(id==='captain'){s.shield=1;s.core.invulnerable=1;}else if(id==='commander')s.pending.push({delay:.1,actor:id,mult:1.2+(1-s.boss.hp/s.boss.maxHp),kind:'power-hunt'});else if(id==='hero'&&s.stats.perfectFlips)s.pending.push({delay:.07,actor:'hero',mult:1.5,kind:'power-perfect'});}
function startSkill(s){const id=s.team[s.skillIndex%s.team.length],ch=CHARACTERS[id],ultimate=(++s.skillCount%3===0);s.skillIndex++;s.skillGauge=0;s.skill={id,motion:ch.motion,ultimate,elapsed:0,duration:ultimate?1.75:1.05,hitMask:0,x:s.core.x,y:s.core.y};s.stats.skills++;if(ultimate)s.stats.ultimates++;emit(s,'skill-intro',{text:ultimate?ch.ultimate:ch.skill,x:180,y:175,life:.65,color:ch.color});if(ch.motion==='support'){const heal=ultimate?25:12;s.hp=Math.min(100,s.hp+heal);s.stats.healing+=heal;s.buff={type:ultimate?'assist':'haste',time:ultimate?4:3};}if(ch.motion==='guard'){s.shield=1;s.buff={type:'guard',time:ultimate?4:2};}}
function updateSkill(s,dt){const k=s.skill;if(!k)return;k.elapsed+=dt;const p=Math.min(1,k.elapsed/k.duration),b=s.boss,actor=k.id;let hits=[];if(k.motion==='slash'){k.x=180+Math.sin(p*Math.PI*4)*110;k.y=b.y+(p<.7?Math.cos(p*Math.PI*3)*55:-130+180*p);hits=k.ultimate?[.18,.34,.5,.68,.88]:[.24,.52,.82];}else if(k.motion==='smash'){k.x=s.core.x+(b.x-s.core.x)*Math.min(1,p*1.7);k.y=s.core.y+(b.y-s.core.y)*Math.min(1,p*1.7);hits=k.ultimate?[.48,.56,.64]:[.52];}else if(k.motion==='support'||k.motion==='guard'){k.x=180;k.y=300;hits=[];}else if(k.motion==='ricochet'){const phase=Math.floor(p*6),side=phase%2?315:45;k.x=phase%2?side+(b.x-side)*(p*6-phase):b.x+(side-b.x)*(p*6-phase);k.y=110+phase*45;hits=[.14,.31,.48,.65,.82];}else if(k.motion==='burn'){k.x=180+Math.sin(p*Math.PI*6)*135;k.y=b.y+Math.cos(p*Math.PI*6)*70;hits=[.14,.28,.42,.56,.7,.84];}else if(k.motion==='pierce'){k.x=30+p*300;k.y=b.y+Math.sin(p*Math.PI*5)*65;hits=k.ultimate?[.2,.36,.52,.68,.84]:[.28,.7];}else if(k.motion==='storm'){k.x=180;k.y=320;hits=Array.from({length:k.ultimate?6:Math.max(2,s.雷能+1)},(_,i)=>(i+1)/(k.ultimate?7:Math.max(3,s.雷能+2)));}else if(k.motion==='hunt'){const low=1-s.boss.hp/s.boss.maxHp;k.x=b.x+Math.sin(p*Math.PI*(4+low*4))*100;k.y=b.y+Math.cos(p*Math.PI*(4+low*4))*70;hits=[.2,.4,.6,.8];}else{k.x=s.core.x+(b.x-s.core.x)*Math.min(1,p*2);k.y=s.core.y+(b.y-s.core.y)*Math.min(1,p*2);hits=k.ultimate?[.3,.48,.66]:[.48];}hits.forEach((at,i)=>{if(p>=at&&!(k.hitMask&(1<<i))){k.hitMask|=1<<i;hit(s,{kind:`skill-${k.motion}`,actor,mult:(k.ultimate?1.45:1.05)+(i===hits.length-1 ? .35 : 0),breakAdd:k.motion==='smash'?28:7,x:k.x,y:k.y});}});if(p>=1){if(k.motion==='storm')s.雷能=0;s.skill=null;}}
export function stepPrototype(s,rawDt){if(!s.running||s.complete)return s;const dt=Math.min(.034,Math.max(0,rawDt));s.timeLeft=Math.max(0,s.timeLeft-dt);if(!s.timeLeft||s.boss.hp<=0){s.running=false;s.complete=true;return s;}if(s.hitStop>0){s.hitStop=Math.max(0,s.hitStop-dt);return s;}s.comboTime=Math.max(0,s.comboTime-dt);if(!s.comboTime){s.combo=0;s.power=0;s.powerTier=0;}s.dashCooldown=Math.max(0,s.dashCooldown-dt);s.breakIn=Math.max(0,s.breakIn-dt);s.core.invulnerable=Math.max(0,s.core.invulnerable-dt);s.boss.flash=Math.max(0,s.boss.flash-dt);s.boss.recoilX*=.94;if(s.buff){s.buff.time-=dt;if(s.buff.time<=0)s.buff=null;}for(const e of s.events)e.life-=dt;s.events=s.events.filter(e=>e.life>0);updateBoss(s,dt);updateSkill(s,dt);for(const q of s.pending)q.delay-=dt;for(const q of s.pending.filter(q=>q.delay<=0))hit(s,q);s.pending=s.pending.filter(q=>q.delay>0);const c=s.core;c.dashTime=Math.max(0,c.dashTime-dt);c.vy+=515*dt;c.x+=c.vx*dt;c.y+=c.vy*dt;c.vx*=Math.pow(s.buff?.type==='combo'?.999:.997,dt*60);if(c.x-c.r<22){c.x=44;c.vx=Math.abs(c.vx)*.9;s.stats.wallHits++;if(s.team.includes('zhangbao'))s.雷能=Math.min(5,s.雷能+1);if(s.team[0]==='blackwind')s.wallStacks=Math.min(3,s.wallStacks+1);}else if(c.x+c.r>338){c.x=316;c.vx=-Math.abs(c.vx)*.9;s.stats.wallHits++;if(s.team.includes('zhangbao'))s.雷能=Math.min(5,s.雷能+1);if(s.team[0]==='blackwind')s.wallStacks=Math.min(3,s.wallStacks+1);}if(c.y-c.r<22){c.y=44;c.vy=Math.abs(c.vy)*.84;}if(c.y+c.r>=482){c.y=460;c.vy=0;c.vx*=.72;c.bottomTime+=dt;}else c.bottomTime=0;s.history.unshift({x:c.x,y:c.y});if(s.history.length>20)s.history.length=20;const dx=c.x-(s.boss.x+s.boss.recoilX),dy=c.y-s.boss.y,overlap=Math.hypot(dx,dy)<72;if(overlap&&!s.bossContact){const leader=s.team[0],mult=1+s.wallStacks*.18;hit(s,{kind:c.powerAttack?'power':'dash',actor:leader,mult,breakAdd:7,x:c.x,y:c.y});if(s.wallStacks)s.wallStacks=0;s.pending.push({delay:.07,actor:s.team[1],mult:.75,kind:'follower'},{delay:.14,actor:s.team[2],mult:.72,kind:'follower'});s.bossContact=true;const d=Math.max(1,Math.hypot(dx,dy)),nx=dx/d,ny=dy/d,dot=c.vx*nx+c.vy*ny;c.x=s.boss.x+nx*73;c.y=s.boss.y+ny*73;c.vx=(c.vx-2*dot*nx)*.88;c.vy=(c.vy-2*dot*ny)*.88;c.powerAttack=0;s.skillGauge=Math.min(100,s.skillGauge+(leader==='guan'&&Math.hypot(c.x-getWeakPoint(s).x,c.y-getWeakPoint(s).y)<50?18:11)*(s.buff?.type==='assist'?1.5:1));s.boss.weakSide=(s.boss.weakSide+1)%3;}if(!overlap)s.bossContact=false;if(s.skillGauge>=100&&!s.skill)startSkill(s);return s;}
export function getFormation(s){const c=s.core,h=s.history,a=h[Math.min(5,h.length-1)]||c,b=h[Math.min(11,h.length-1)]||a,angle=Math.atan2(c.vy,c.vx),px=-Math.sin(angle),py=Math.cos(angle);return[{x:c.x,y:c.y,angle,id:s.team[0]},{x:a.x+px*22,y:a.y+py*22,angle,id:s.team[1]},{x:b.x-px*22,y:b.y-py*22,angle,id:s.team[2]}];}
export function getResults(s){return{team:s.team,highestCombo:s.maxCombo,...s.stats,hp:Math.round(s.hp)};}
